import { NextResponse } from 'next/server';
import { OAuth2Client } from 'google-auth-library';
import { db } from '@/lib/db';
import { signJwtToken } from '@/lib/auth';

export async function GET(req: Request) {
  try {
    const { searchParams } = new URL(req.url);
    const code = searchParams.get('code');
    const error = searchParams.get('error');

    const baseUrl = process.env.NEXT_PUBLIC_BASE_URL || 'http://localhost:3000';
    const redirectUri = `${baseUrl}/api/auth/google/callback`;

    // User denied access
    if (error || !code) {
      return NextResponse.redirect(`${baseUrl}/?auth_error=google_denied`);
    }

    const clientId = process.env.GOOGLE_CLIENT_ID;
    const clientSecret = process.env.GOOGLE_CLIENT_SECRET;

    if (!clientId || !clientSecret) {
      return NextResponse.redirect(`${baseUrl}/?auth_error=google_not_configured`);
    }

    const oauth2Client = new OAuth2Client(clientId, clientSecret, redirectUri);

    // Exchange code for tokens
    const { tokens } = await oauth2Client.getToken(code);
    oauth2Client.setCredentials(tokens);

    // Verify the ID token and extract user info
    const ticket = await oauth2Client.verifyIdToken({
      idToken: tokens.id_token!,
      audience: clientId,
    });

    const payload = ticket.getPayload();
    if (!payload || !payload.email) {
      return NextResponse.redirect(`${baseUrl}/?auth_error=google_no_email`);
    }

    const { email, name, sub: googleId, picture: avatar } = payload;
    const displayName = name || email.split('@')[0];

    // Find or create user
    let user = await db.user.findUnique({ where: { email } });

    if (!user) {
      // New Google user — create account
      user = await db.user.create({
        data: {
          name: displayName,
          email,
          passwordHash: `google_oauth_${googleId}`,
          avatar: avatar || null,
          role: 'user',
        },
      });
    } else if (avatar && user.avatar !== avatar) {
      // Update avatar if it changed (Google may update profile pics)
      user = await db.user.update({
        where: { id: user.id },
        data: { avatar },
      });
    }

    // Issue JWT — avatar is included so Navbar can display it without extra DB calls
    const token = signJwtToken({
      userId: user.id,
      email: user.email,
      name: user.name,
      role: user.role,
      avatar: user.avatar || undefined,
    });

    // Redirect to home with cookie set
    const response = NextResponse.redirect(`${baseUrl}/?google_login=success`);
    response.cookies.set('byom_auth_token', token, {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'lax',
      maxAge: 60 * 60 * 24 * 7, // 7 days
      path: '/',
    });

    return response;
  } catch (error: any) {
    console.error('[Google OAuth callback error]', error);
    const baseUrl = process.env.NEXT_PUBLIC_BASE_URL || 'http://localhost:3000';
    return NextResponse.redirect(`${baseUrl}/?auth_error=google_failed`);
  }
}
